INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Nội dung nào thể hiện sự linh hoạt, sáng tạo của Bộ Chính trị Trung ương Đảng trong việc đề ra kế hoạch giải phóng hoàn toàn miền Nam trong hai năm 1975 và 1976?', 'C', 'Trong chủ trương, kế hoạch giải phóng hoàn toàn miền Nam, điểm khẳng định sự lãnh đạo đúng đắn và linh hoạt của Đảng, đó là: Bộ Chính trị nhấn mạnh: “Nếu thời cơ đến vào đầu hoặc cuối năm 1975, thì lập tức giải phóng miền Nam trong năm 1975”. Chủ trương này được đề ra trên cơ sở nhận đúng đúng đắn tình hình cách mạng nước ta, trong hoàn cảnh so sánh lực lượng có lợi cho cách mạng Việt Nam.
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'Tổng tiến công và nổi dậy ở Tây Nguyên, Huế - Đà Nẵng rồi tiến về Sài Gòn.');
