INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Sự kiện nào mở ra kỷ nguyên độc lập, thống nhất, đi lên chủ nghĩa xã hội của Việt Nam?', 'C', 'Thắng lợi của cuộc kháng chiến chống Mĩ cứu nước đã mở ra kỉ nguyên mới trong lịch sử dân tộc – kỉ nguyên đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.
