INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Hiệp định về những cơ sở của quan hệ giữa Đông Đức và Tây Đức (1972) và Định ước Henxinki (1975) đều chủ trương', 'B', '-	Hiệp định về những cơ sở quan hệ giữa Đông Đức và Tây Đức (1972) có nội dung: Hai bên thiết lập quan hệ láng giềng thân thiện trên cơ sở bình đẳng và giải quyết các vấn đề tranh chấp bằng biện pháp hòa bình.
