INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Trong thập niên 90 của thế kỷ XX, các cuộc xung đột quân sự xảy ra ở bán đảo Bancăng và một số nước châu Phi là một trong những', 'A', 'Sau Chiến tranh lạnh, hòa bình thế giới được củng cố, nhưng ở nhiều khu vực tình hình lại không ổn định với những cuộc nội chiến, xung đột quân sự đẫm máu kéo dài như ở bán đảo Bancăng, một số nước ở châu Phi và Trung Á.
