INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Đặc điểm của phong trào dân tộc dân chủ ở Việt Nam từ sau Chiến tranh thế giới thứ nhất đến đầu năm 1930 là', 'D', 'Đặc điểm cơ bản nhất của lịch sử Việt Nam giai đoạn 1919-1930 là cuộc đấu tranh giành quyền lãnh đạo duy nhất đối với cách mạng Việt Nam giữa 2 khuynh hướng tư sản và vô sản:
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'khuynh hướng vô sản phát triển nhờ kinh nghiệm của khuynh hướng tư sản.');
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'B', 'cả hai khuynh hướng tư sản và vô sản đều sử dụng bạo lực để loại trừ nhau.');
