INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Cuộc chiến đấu của quân dân Việt Nam tại các đô thị phía Bắc vĩ tuyến 16 từ cuối năm 1946 đến đầu năm 1947 có nhiệm vụ trọng tâm là', 'B', 'Trong 60 ngày đêm, quân dân Hà Nội đã hoàn thành xuất sắc nhiệm vụ giam chân địch trong thành phố một thời gian dài để hậu phương kịp thời huy động lực lượng kháng chiến, di chuyển kho tàng, công xưởng về chiến khu, bảo vệ trung ương Đảng, chính phủ về căn cứ lãnh đạo kháng chiến.
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'giữ thế chủ động trên chiến trường chính Bắc Bộ.');
