INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'D', 'tiêu diệt toàn bộ binh lực Pháp.');
INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Cuộc kháng chiến chống Mỹ, cứu nước (1954 - 1975) của nhân dân Việt Nam thắng lợi làmột sự kiện có tầm quan trọng quốc tế to lớn và tính thời đại sâu sắc vì đã', 'A', 'Mĩ xâm lược Việt Nam với âm mưu: chia cắt hai miền Nam – Bắc, biến miền Nam thành thuộc địa kiểu mới và căn cứ quân sự Mĩ ở Đông Dương và Đông Nam Á. Chính vì thế, cuộc kháng chiến chống Mĩ của nhân dân Việt Nam thắng lợi đã giáng đòn mạnh vào âm mưu nô dịch của chủ nghĩa thực dân, cổ vũ và tác động đến phong trào giải phóng dân tộc của nhiều quốc gia trên thế giới. Chính vì thế, cuộc kháng chiến chống Mĩ cứu nước của nhân dân Việt Nam thắng lợi là sự kiện có tầm quan trọng quốc tế to lớn và có tính thời đại sâu sắc.
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'giáng đòn mạnh mẽ vào âm mưu nô dịch của chủ nghĩa thực dân.');
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'B', 'tạo ra tác động cơ bản làm sụp đổ trật tự thế giới hai cực Ianta.');
