INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'D', 'chưa được quần chúng nhân dân ủng hộ.');
INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Từ năm 1991 đến năm 2000, các nước lớn điều chỉnh quan hệ theo hướng đối thoại, thỏa hiệp, tránh xung đột trực tiếp chủ yếu vì', 'D', 'Một đặc điểm lớn của tình hình thế giới sau Chiến tranh lạnh là sự điều chỉnh quan hệ giữa các nước lớn theo chiều hướng đối thoại, thỏa hiệp, tránh xung đột trực tiếp nhằm tạo nên một môi trường quốc tế thuận lợi, giúp họ vương lên mạnh mẽ, xác lập vị trí ưu thế trong trật tự thế giới mới.
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'hợp tác chính trị - quân sự trở thành nội dung căn bản trong quan hệ quốc tế.');
