INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'D', 'muốn tạo môi trường quốc tế thuận lợi để vươn lên xác lập vị thế.');
INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Nội dung nào là điểm tương đồng giữa phong trào giải phóng dân tộc ở châu Phi và khu vực Mỹ Latinh sau Chiến tranh thế giới thứ hai?', 'B', 'Phong trào giải phóng dân tộc ở châu Phi và khu vực Mĩ Latinh đều giành thắng lợi, đưa đến thành lập hàng loạt các nhà nước độc lập.
