INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Đầu năm 1930, khuynh hướng vô sản thắng thế hoàn toàn khuynh hướng tư sản ở Việt Nam vì', 'C', 'Khướng cách mạng dân chủ tư sản xuất phát từ châu Âu từ thế kỉ XVII, khuynh hướng vô sản bắt đầu từ nước Nga, đặc biệt ảnh hướng đến Việt Nam từ sau Cách mạng tháng Mười Nga (1917), đây là khuynh hướng cách mạng tiên tiến, đáp ứng yêu cầu của lịch sử là cần phải có giap cấp lãnh đạo đại diện cho quyền lợi của giai cấp công nhân và nông dân (vốn là hai lực lượng đông đảo nhất trong cách mạng Việt Nam) để chống Pháp, giành độc lập dân tộc. Trong khi đó, giai cấp tư sản đại diện cho khuynh hướng dân chủ tư sản lúc này còn non yếu về chính trị, nhỏ bé về kinh tế. Khuynh hướng vô sản phù hợp với yêu cầu của lịch sử hơn rất nhiều so với khuynh hướng dân chủ tư sản đang lỗi thời.
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'A', 'khuynh hướng vô sản giải quyết triệt để tất cả mâu thuẫn trong xã hội Việt Nam.');
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'B', 'giai cấp công nhân chiếm tỉ lệ lớn nhất trong cơ cấu xã hội Việt Nam.');
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'C', 'khuynh hướng vô sản đáp ứng được yêu cầu khách quan của sự nghiệp giải phóng dân tộc.');
INSERT INTO question_options (question_id, letter, content) VALUES ((SELECT MAX(id) FROM questions), 'D', 'khuynh hướng vô sản giải quyết được yêu cầu ruộng đất của giai cấp nông dân Việt Nam.');
INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Điểm mới của Nghị quyết Hội nghị lần thứ 8 Ban Chấp hành Trung ương tháng 5 - 1941 so với Luận cương chính trị tháng 10 - 1930 của Đảng Cộng sản Đông Dương là chủ trương', 'A', '- Hội nghị trung ương Đảng tháng 5-1941 đã chủ trương sau khi đánh đuổi đế quốc Pháp- Nhật sẽ thành lập chính phủ nhân dân của nước Việt Nam Dân chủ Cộng hòa
