INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Trong chiến dịch Hồ Chí Minh năm 1975, lực lượng chính trị giữ vai trò', 'A', 'Trong chiến dịch Hồ Chí Minh, lực lượng chính trị giữ vai trò hỗ trợ lực lượng vũ trang. Vì trong thực tế diễn biến chiến dịch, lực lượng vũ trang là lực lượng vũ trang là lực lượng xung kích, nòng cốt, giữ vai trò quyết định trong việc đánh bại chính quyền Việt Nam Cộng hòa, còn lực lượng chính trị chỉ là những người dẫn đường giúp quân giải phóng có thể tiến vào giải phóng Sài Gòn thuận lợi
