INSERT INTO questions (question_text, correct_letter, explanation) VALUES ('Điểm chung của Cách mạng tháng Tám năm 1945, kháng chiến chống thực dân Pháp (1945 - 1954) và kháng chiến chống Mỹ, cứu nước (1954 - 1975) ở Việt Nam là có sự kết hợp', 'B', 'Điểm chung của cách mạng tháng Tám năm 1945, kháng chiến chống thực dân Pháp (1945-1954) và kháng chiến chống Mĩ (1954-1975) là có sự kết hợp giữa lực lượng chính trị với lực lượng vũ trang để tạo nên sức mạnh tổng hợp của toàn dân tộc.
